__mods['./config'] = function (module, exports, require) {
'use strict';
/**
 * Converte variáveis de ambiente (strings) num objeto de configuração tipado.
 * Todo workflow/roteiro chama lerConfig() no início; nenhuma outra parte lê `env` direto.
 */

function bool(v, padrao) {
  if (v === undefined || v === null || v === '') return padrao;
  return ['1', 'true', 'sim', 'yes', 'on'].includes(String(v).trim().toLowerCase());
}
function int(v, padrao) {
  const n = parseInt(v, 10);
  return Number.isFinite(n) ? n : padrao;
}
function lista(v, padrao) {
  if (v === undefined || v === null || String(v).trim() === '') return padrao;
  return String(v).split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
}

/**
 * @param {Record<string,string|undefined>} env  ex.: process.env ou $env do n8n
 */
function lerConfig(env = {}) {
  return {
    tz: env.TZ || 'America/Sao_Paulo',
    canais: {
      telegram: bool(env.CANAL_TELEGRAM_ATIVO, true),
      whatsapp: bool(env.CANAL_WHATSAPP_ATIVO, false),   // Fase 5
      email: bool(env.CANAL_EMAIL_ATIVO, false),         // entrada por e-mail: Fase 3
      forms: bool(env.CANAL_FORMS_ATIVO, false),         // Fase 3
    },
    notificacoes: {
      telegram: bool(env.NOTIFICACAO_TELEGRAM_ATIVA, true),
      whatsapp: bool(env.NOTIFICACAO_WHATSAPP_ATIVA, false),
      email: bool(env.NOTIFICACAO_EMAIL_ATIVA, true),
    },
    features: {
      rodizio: bool(env.FEATURE_RODIZIO, true),
      reversao: bool(env.FEATURE_REVERSAO, true),
      drive: bool(env.FEATURE_DRIVE, true),
      fluxograma: bool(env.FEATURE_FLUXOGRAMA, false),      // Fase 3
      iaDocumentos: bool(env.FEATURE_IA_DOCUMENTOS, false), // Fase 4
      // TODO(ENVIO_AUTOMATICO_CLIENTE): quando implementado, o efeito `enviar_documento_cliente` usa esta flag.
      envioAutomaticoCliente: bool(env.ENVIO_AUTOMATICO_CLIENTE, false),
    },
    sla: {
      lembreteIntervaloHoras: int(env.LEMBRETE_INTERVALO_HORAS, 24),
      escalonarAposLembretes: int(env.ESCALONAR_APOS_LEMBRETES, 2),
      diasAutoAbandono: int(env.DIAS_AUTO_ABANDONO, 30),
      horarioInicio: env.HORARIO_NOTIFICACAO_INICIO || '08:00',
      horarioFim: env.HORARIO_NOTIFICACAO_FIM || '21:00',
      notificarFimDeSemana: bool(env.NOTIFICAR_FIM_DE_SEMANA, false),
      tz: env.TZ || 'America/Sao_Paulo',
    },
    exigirResponsavelAtribuido: bool(env.EXIGIR_RESPONSAVEL_ATRIBUIDO, false),
    janelaReversaoHoras: int(env.JANELA_REVERSAO_HORAS, 48),
    sessaoTtlMin: int(env.SESSAO_TTL_MIN, 30),
    rateLimitPorMin: int(env.RATE_LIMIT_POR_MIN, 20),
    arquivoTamanhoMaxMb: int(env.ARQUIVO_TAMANHO_MAX_MB, 20),
    arquivoExtensoes: lista(env.ARQUIVO_EXTENSOES_PERMITIDAS,
      ['pdf', 'png', 'jpg', 'jpeg', 'docx', 'xlsx', 'zip', 'stl', '3mf', 'step']),
    driveRaizId: env.DRIVE_RAIZ_ID || '',
    emailRemetente: env.EMAIL_REMETENTE || 'Therion Bot <fluxo@example.com>',
    telegramApiBase: (env.TELEGRAM_API_BASE || 'https://api.telegram.org').replace(/\/+$/, ''),
  };
}

module.exports = { lerConfig };

};
__mods['./render'] = function (module, exports, require) {
'use strict';
/**
 * Renderização por canal: transforma mensagens neutras em "envios" prontos para o WF-05.
 *   telegram -> { canal:'telegram', membro_id, registrar, telegram: { metodo, corpo } }   (Bot API)
 *   email    -> { canal:'email',    membro_id, registrar, email: { para, assunto, texto } }
 */

const LIMITE_TELEGRAM = 4096;

/** Quebra um texto longo em partes de até `limite`, preferindo quebras de linha. */
function dividirTexto(texto, limite = LIMITE_TELEGRAM) {
  const partes = [];
  let resto = String(texto ?? '');
  while (resto.length > limite) {
    let corte = resto.lastIndexOf('\n', limite);
    if (corte < limite / 2) corte = limite;
    partes.push(resto.slice(0, corte));
    resto = resto.slice(corte).replace(/^\n/, '');
  }
  if (resto || !partes.length) partes.push(resto);
  return partes;
}

/** Só notificações vão para a tabela `notificacoes`; respostas diretas e mensagens sigilosas (código de vínculo) não. */
function deveRegistrar(msg) { return !msg.resposta_direta && !msg.sigiloso; }

function tecladoTelegram(botoes) {
  if (!botoes || !botoes.length) return undefined;
  return {
    inline_keyboard: botoes.map((b) => [{
      text: String(b.rotulo).slice(0, 60),
      callback_data: String(b.dados).slice(0, 64),   // limite da Bot API
    }]),
  };
}

function renderTelegram(msg) {
  const partes = dividirTexto(msg.texto || ' ');
  return partes.map((texto, i) => {
    const corpo = { chat_id: msg.destino, text: texto || ' ', disable_web_page_preview: true };
    const teclado = i === partes.length - 1 ? tecladoTelegram(msg.botoes) : undefined;
    if (teclado) corpo.reply_markup = teclado;
    return { canal: 'telegram', membro_id: msg.membro_id || null, registrar: deveRegistrar(msg), telegram: { metodo: 'sendMessage', corpo } };
  });
}

function renderEmail(msg) {
  let texto = msg.texto || '';
  if (msg.botoes && msg.botoes.length) texto += '\n\nPara agir, use o bot no Telegram.';
  return [{
    canal: 'email', membro_id: msg.membro_id || null, registrar: deveRegistrar(msg),
    // essencial = sai mesmo com NOTIFICACAO_EMAIL_ATIVA=false (ex.: código de vínculo, que só existe por e-mail)
    essencial: !!msg.sigiloso,
    email: { para: msg.destino, assunto: msg.assunto || 'Therion Fluxo', texto },
  }];
}

/**
 * @param {object[]} mensagens  [{canal, destino, texto, botoes?, assunto?, membro_id?}]
 * @param {{id:string}|null} callback  se a entrada foi um clique de botão, responde-o (tira o "carregando")
 */
function montarEnvios(mensagens, callback = null) {
  const envios = [];
  if (callback && callback.id) {
    envios.push({ canal: 'telegram', membro_id: null, registrar: false,
      telegram: { metodo: 'answerCallbackQuery', corpo: { callback_query_id: callback.id } } });
  }
  for (const m of mensagens || []) {
    if (!m || !m.destino) continue;
    if (m.canal === 'telegram') envios.push(...renderTelegram(m));
    else if (m.canal === 'email') envios.push(...renderEmail(m));
  }
  return envios;
}

module.exports = { montarEnvios, renderTelegram, renderEmail, dividirTexto, tecladoTelegram, LIMITE_TELEGRAM };

};
